```
package main
import (
	"encoding/json"
	"fmt"
	"strings"
)
type Syllable struct {
	VowelSounds     []string `json:"vowelSounds"`
	ConsonantSounds []string `json:"consonantSounds"`
}
type Word struct {
	Word      string     `json:"word"`
	Syllables []Syllable `json:"syllables"`
}
func main() {
	jsonData := `{
		"word": "Protagonist",
		"syllables": [
			{
				"vowelSounds": [
					"ow"
				]
			},
			{
				"consonantSounds": [
					"t",
					"g",
					"n",
					"s",
					"t"
				]
			}
		]
	}`
	var wordData Word
	err := json.Unmarshal([]byte(jsonData), &wordData)
	if err != nil {
		panic(err)
	}
	numBeats := 0
	for _, syllable := range wordData.Syllables {
		numBeats += countBeats(syllable.VowelSounds[0])
		numBeats += countBeats(strings.Join(syllable.ConsonantSounds, ""))
	}
	fmt.Printf("The word \"%s\" has %d beats.\n", wordData.Word, numBeats)
}
func countBeats(sounds string) int {
	numBeats := 0
	for _, sound := range sounds {
		switch sound {
		case 'a', 'e', 'i', 'o', 'u', 'y':
			numBeats++
		}
	}
	return numBeats
}
```
