To implement the recycling quiz in an HTML page, you can use JavaScript to display the questions and handle user input. Here's an example of how you can modify the Ruby code to work with JavaScript:
```ruby
# Define questions and answers
questions = [
  "What should you do with plastic bags?",
  "Which of the following items can be recycled?",
  "How many times can glass be recycled?"
]
answers = [
  "Reuse them or recycle them at a grocery store drop-off location.",
  "Paper, cardboard, glass, metal, and plastic bottles and containers.",
  "Indefinitely."
]
# Convert questions and answers to JSON format
quiz_data = { questions: questions, answers: answers }.to_json
```
Then, in your HTML file, you can use JavaScript to display the questions and handle user input:
```html
<!DOCTYPE html>
<html>
<head>
  <title>Recycling Quiz</title>
</head>
<body>
  <h1>Recycling Quiz</h1>
  <div id="quiz"></div>
  <button id="submit">Submit</button>
  <div id="score"></div>
  <script>
    // Parse JSON data and create quiz
    const quizData = JSON.parse('<%= quiz_data %>');
    const quizElement = document.getElementById('quiz');
    const submitButton = document.getElementById('submit');
    const scoreElement = document.getElementById('score');
    let score = 0;
    quizData.questions.forEach((question, index) => {
      const questionElement = document.createElement('div');
      questionElement.innerHTML = `<p>${index + 1}. ${question}</p>`;
      quizElement.appendChild(questionElement);
      const answerInput = document.createElement('input');
      answerInput.type = 'text';
      quizElement.appendChild(answerInput);
    });
    // Handle user input and calculate score
    submitButton.addEventListener('click', () => {
      const answerInputs = quizElement.querySelectorAll('input');
      answerInputs.forEach((input, index) => {
        if (input.value.toLowerCase() === quizData.answers[index].toLowerCase()) {
          score++;
          input.style.backgroundColor = 'lightgreen';
        } else {
          input.style.backgroundColor = 'pink';
        }
        input.disabled = true;
      });
      scoreElement.innerHTML = `You scored ${score}/${quizData.questions.length}. Remember to recycle and reduce waste to help protect the environment.`;
    });
  </script>
</body>
</html>
