A retail company can benefit from implementing blockchain technology in its supply chain management system by ensuring transparency and traceability in the movement of goods from manufacturer to customer. Blockchain technology can help in creating a decentralized and secure system that can track the movement of goods at every stage of the supply chain. This can help in reducing fraud, minimizing errors, and improving the overall efficiency of the supply chain.
Here is a sample Java code that demonstrates how blockchain can be used to ensure transparency and traceability in the movement of goods from manufacturer to customer:
```
import java.util.ArrayList;
import java.util.Date;
public class Block {
    public String hash;
    public String previousHash;
    private String data;
    private long timeStamp;
    public Block(String data, String previousHash ) {
        this.data = data;
        this.previousHash = previousHash;
        this.timeStamp = new Date().getTime();
        this.hash = calculateHash();
    }
    public String calculateHash() {
        String calculatedhash = StringUtil.applySha256(
                previousHash +
                Long.toString(timeStamp) +
                data
                );
        return calculatedhash;
    }
}
public class Blockchain {
    public static ArrayList<Block> blockchain = new ArrayList<Block>();
    public static int difficulty = 5;
    public static Boolean isChainValid() {
        Block currentBlock;
        Block previousBlock;
        String hashTarget = new String(new char[difficulty]).replace('\0', '0');
        for(int i=1; i < blockchain.size(); i++) {
            currentBlock = blockchain.get(i);
            previousBlock = blockchain.get(i-1);
            if(!currentBlock.hash.equals(currentBlock.calculateHash()) ){
                System.out.println("Current Hashes not equal");
                return false;
            }
            if(!previousBlock.hash.equals(currentBlock.previousHash) ) {
                System.out.println("Previous Hashes not equal");
                return false;
            }
            if(!currentBlock.hash.substring( 0, difficulty).equals(hashTarget)) {
                System.out.println("This block hasn't been mined");
                return false;
            }
        }
        return true;
    }
    public static void addBlock(Block newBlock) {
        newBlock.mineBlock(difficulty);
        blockchain.add(newBlock);
    }
}
public class Main {
    public static void main(String[] args) {
        // Add the first block
        Blockchain.addBlock(new Block("First Block", "0"));
        // Add the second block
        Blockchain.addBlock(new Block("Second Block", Blockchain.blockchain.get(Blockchain.blockchain.size()-1).hash));
        // Add the third block
        Blockchain.addBlock(new Block("Third Block", Blockchain.blockchain.get(Blockchain.blockchain.size()-1).hash));
        // Check if the blockchain is valid
        System.out.println("Is the blockchain valid? " + Blockchain.isChainValid());
        // Print the blockchain
        System.out.println("Blockchain: " + Blockchain.blockchain);
    }
}
