To randomize the order of the given sentences and output them in a way that forms a complete story while ensuring grammatical correctness and coherence, we can use the following steps in C++:
1. Create an array or vector of strings containing the sentences to be randomized.
2. Randomize the order of the sentences in the array or vector using the `random_shuffle` function from the `<algorithm>` library.
3. Iterate over the randomized array or vector of sentences and check for a common word with the previous sentence.
4. If a common word is found, output the current sentence. If not, keep iterating until a sentence with a common word is found.
5. Continue iterating until all sentences have been output.
Here's an example implementation of the above steps in C++:
```
#include <iostream>
#include <vector>
#include <algorithm>
#include <string>
using namespace std;
// Function to check if two sentences have a common word
bool hasCommonWord(string s1, string s2) {
    for (string::iterator it = s1.begin(); it != s1.end(); it++) {
        if (*it == ' ') {
            string word = s1.substr(0, it - s1.begin());
            if (s2.find(word) != string::npos) {
                return true;
            }
            s1.erase(0, it - s1.begin() + 1);
            it = s1.begin();
        }
    }
    return false;
}
int main() {
    // Array of sentences to be randomized
    string sentences[] = {
        "The quick brown fox jumps over the lazy dog.",
        "She sells seashells by the seashore.",
        "The cat in the hat.",
        "To be or not to be, that is the question.",
        "I have a dream that one day this nation will rise up and live out the true meaning of its creed.",
        "Ask not what your country can do for you, ask what you can do for your country."
    };
    // Vector to store randomized sentences
    vector<string> randomizedSentences(sentences, sentences + sizeof(sentences) / sizeof(sentences[0]));
    random_shuffle(randomizedSentences.begin(), randomizedSentences.end());
    // Output randomized sentences with common words
    cout << randomizedSentences[0] << endl;
    for (int i = 1; i < randomizedSentences.size(); i++) {
        while (!hasCommonWord(randomizedSentences[i - 1], randomizedSentences[i])) {
            random_shuffle(randomizedSentences.begin(), randomizedSentences.end());
        }
        cout << randomizedSentences[i] << endl;
    }
    return 0;
}
```
In this example, we first create an array of sentences to be randomized. We then create a vector to store the randomized sentences and use the `random_shuffle` function to randomize the order of the sentences.
We then iterate over the randomized sentences and check for a common word with the previous sentence using the `hasCommonWord` function. If a common word is found, we output the current sentence. If not, we keep randomizing the order of the sentences until a sentence with a common word is found.
Finally, we output all the randomized sentences with common words to form a complete story.

